public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.size() < 2) {
        return 0;
    }
    int maxLength = 0;
    for (int i = 0; i < strings.size(); i++) {
        String s1 = strings.get(i);
        if (s1 == null) continue;
        for (int j = i + 1; j < strings.size(); j++) {
            String s2 = strings.get(j);
            if (s2 == null) continue;
            int lenLimit = Math.min(s1.length(), s2.length());
            for (int len = lenLimit; len > maxLength; len--) {
                // try all substrings of s1 of this length
                boolean found = false;
                for (int start = 0; start <= s1.length() - len && !found; start++) {
                    String sub = s1.substring(start, start + len);
                    String rev = new StringBuilder(sub).reverse().toString();
                    if (s2.contains(sub) || s2.contains(rev)) {
                        found = true;
                    }
                }
                if (found) {
                    maxLength = len;
                    break; // no need to check smaller lengths for this pair
                }
            }
            if (maxLength == Math.min(s1.length(), s2.length())) {
                // can't get longer with any other pair
                return maxLength;
            }
        }
    }
    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Check for null elements and replace them with empty strings
    List<String> cleaned = new ArrayList<>(strings.size());
    for (String s : strings) {
        cleaned.add(s == null ? "" : s);
    }

    String first = cleaned.get(0);
    int n = first.length();

    // Handle the trivial case of a single string
    if (cleaned.size() == 1) {
        return n;
    }

    for (int len = n; len >= 1; len--) {
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i + len <= n; i++) {
            substrings.add(first.substring(i, i + len));
        }

        for (String sub : substrings) {
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int idx = 1; idx < cleaned.size(); idx++) {
                String current = cleaned.get(idx);
                if (!(current.contains(sub) || current.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    for (String s : strings) {
        if (s != null) {
            maxLen = Math.max(maxLen, s.length());
        }
    }

    for (int len = maxLen; len >= 1; len--) {
        Set<String> common = null;
        for (String s : strings) {
            if (s == null || s.length() < len) {
                common = new HashSet<>();
                break;
            }
            Set<String> curr = new HashSet<>();
            // substrings of the original string
            for (int i = 0; i <= s.length() - len; i++) {
                curr.add(s.substring(i, i + len));
            }
            // substrings of the reversed string
            String rev = new StringBuilder(s).reverse().toString();
            for (int i = 0; i <= rev.length() - len; i++) {
                curr.add(rev.substring(i, i + len));
            }
            if (common == null) {
                common = curr;
            } else {
                common.retainAll(curr);
            }
            if (common.isEmpty()) {
                break; // no need to check further strings
            }
        }
        if (common != null && !common.isEmpty()) {
            return len;
        }
    }
    return 0;
}

