    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    // Build frequency map
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        // Only even numbers can be double of an int
        if (num % 2 == 0) {
            int half = num / 2;
            Integer halfCount = freq.get(half);
            if (halfCount != null) {
                if (half != num) {
                    // different number exists
                    count++;
                } else if (halfCount > 1) {
                    // same number appears at least twice
                    count++;
                }
            }
        }
    }
    return count;
}

