public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null ||
            start.length != n || end.length != n) {
            return "cannot be travelled";
        }

        // Helper to convert coordinates to a unique string key
        java.util.function.Function<int[], String> coordToKey = coord -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coord.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(coord[i]);
            }
            return sb.toString();
        };

        String startKey = coordToKey.apply(start);
        String endKey = coordToKey.apply(end);

        java.util.Map<String, java.util.Set<String>> graph = new java.util.HashMap<>();
        graph.put(startKey, new java.util.HashSet<>());
        graph.put(endKey, new java.util.HashSet<>());

        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                continue; // ignore malformed path
            }
            int[] coordA = java.util.Arrays.copyOfRange(path, 0, n);
            int[] coordB = java.util.Arrays.copyOfRange(path, n, 2 * n);
            String keyA = coordToKey.apply(coordA);
            String keyB = coordToKey.apply(coordB);
            graph.computeIfAbsent(keyA, k -> new java.util.HashSet<>()).add(keyB);
            graph.computeIfAbsent(keyB, k -> new java.util.HashSet<>()).add(keyA);
        }

        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Deque<String> queue = new java.util.ArrayDeque<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (current.equals(endKey)) {
                return "can be travelled";
            }
            for (String neighbor : graph.getOrDefault(current, java.util.Collections.emptySet())) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.add(neighbor);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    String startKey = coordToKey(start, n);
    String endKey = coordToKey(end, n);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency list
    Map<String, List<String>> graph = new HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 2 * n) {
                continue; // skip invalid path entry
            }
            int[] a = new int[n];
            int[] b = new int[n];
            System.arraycopy(p, 0, a, 0, n);
            System.arraycopy(p, n, b, 0, n);
            String aKey = coordToKey(a, n);
            String bKey = coordToKey(b, n);
            graph.computeIfAbsent(aKey, k -> new ArrayList<>()).add(bKey);
            graph.computeIfAbsent(bKey, k -> new ArrayList<>()).add(aKey);
        }
    }

    // Breadth‑first search for connectivity
    Deque<String> queue = new ArrayDeque<>();
    Set<String> visited = new HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.pollFirst();
        List<String> neighbors = graph.get(current);
        if (neighbors == null) {
            continue;
        }
        for (String nb : neighbors) {
            if (visited.contains(nb)) {
                continue;
            }
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nb);
            queue.addLast(nb);
        }
    }
    return "cannot be travelled";
}

