        if (sx < 0 || sx >= n || sy < 0 || sy >= n) return "cannot be travelled";
        if (ex < 0 || ex >= n || ey < 0 || ey >= n) return "cannot be travelled";
        long startKey = (((long) sx) << 32) | (sy & 0xffffffffL);
        long endKey = (((long) ex) << 32) | (ey & 0xffffffffL);
        if (startKey == endKey) return "can be travelled";
        java.util.Map<Long, java.util.List<Long>> adj = new java.util.HashMap<>();
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n) continue;
            if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
            long key1 = (((long) x1) << 32) | (y1 & 0xffffffffL);
            long key2 = (((long) x2) << 32) | (y2 & 0xffffffffL);
            adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
            adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
        }
        java.util.Set<Long> visited = new java.util.HashSet<>();
        java.util.ArrayDeque<Long> queue = new java.util.ArrayDeque<>();
        queue.add(startKey);
        visited.add(startKey);
        while (!queue.isEmpty()) {
            long cur = queue.poll();
            java.util.List<Long> neighbors = adj.get(cur);
            if (neighbors == null) continue;
            for (long nxt : neighbors) {
                if (!visited.contains(nxt)) {
                    if (nxt == endKey) return "can be travelled";
                    visited.add(nxt);
                    queue.add(nxt);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
