public static String convertDatesToWeekdays(String date) {
    if (date == null || date.isBlank()) {
        return "";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "";
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.format.DateTimeFormatter monthNameFmt = java.time.format.DateTimeFormatter.ofPattern("MMMM");
        java.time.format.DateTimeFormatter dayOfWeekFmt = java.time.format.DateTimeFormatter.ofPattern("EEEE");

        String monthName = monthNameFmt.format(localDate);
        String dayOfWeek = dayOfWeekFmt.format(localDate);

        return String.format("%s %d, %d is a %s", monthName, day, year, dayOfWeek);
    } catch (Exception e) {
        return "";
    }
}

