public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.floor(n * 0.05);
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (double)(n - 2 * k);
}

