    if (k < 0) k = 0;
    if (n <= 2 * k) {
        // If the array is too small to remove the required elements, return 0.0
        return 0.0;
    }
    java.util.Arrays.sort(arr);
    double sum = 0.0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    return sum / (n - 2 * k);
}

