    // Sort the array (using fully qualified name to avoid imports)
    java.util.Arrays.sort(arr);
    long sum = 0;
    int count = 0;
    for (int i = m; i < n - m; i++) {
        sum += arr[i];
        count++;
    }
    if (count == 0) {
        return 0.0;
    }
    return ((double) sum) / count;
