public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0 && (count[k / 2] % 2 != 0)) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            continue; // already handled when k is even
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

