        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        java.util.HashSet<Integer> set = dp[k];
        if (set != null && set.contains(target)) return true;
    }
    return false;
