        for (int k = Math.min(n - 1, dp.length - 1); k >= 1; k--) {
            if (dp[k - 1].isEmpty()) continue;
            java.util.HashSet<Integer> currentSet = dp[k];
            java.util.HashSet<Integer> prevSet = dp[k - 1];
            for (int prevSum : prevSet) {
                currentSet.add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    int maxK = n / 2;

    // dp[k] will contain all possible sums achievable using k elements
    List<Set<Integer>> dp = new ArrayList<>(maxK + 1);
    for (int i = 0; i <= maxK; i++) {
        dp.add(new HashSet<>());
    }
    dp.get(0).add(0);

    for (int idx = 0; idx < nums.length; idx++) {
        int num = nums[idx];
        int limit = Math.min(maxK, idx + 1);
        for (int k = limit; k >= 1; k--) {
            Set<Integer> prevSet = dp.get(k - 1);
            if (prevSet.isEmpty()) {
                continue;
            }
            Set<Integer> currentSet = dp.get(k);
            for (int prevSum : prevSet) {
                currentSet.add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        if (total * k % n != 0) {
            continue;
        }
        int targetSum = total * k / n;
        if (dp.get(k).contains(targetSum)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int maxSize = n / 2;
    // dp[size][sum] == true if a subset of length 'size' can sum to 'sum'
    boolean[][] dp = new boolean[maxSize + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int size = Math.min(maxSize, n); size >= 1; size--) {
            for (int sum = totalSum; sum >= num; sum--) {
                if (dp[size - 1][sum - num]) {
                    dp[size][sum] = true;
                }
            }
        }
    }
    for (int size = 1; size <= maxSize; size++) {
        if ((totalSum * size) % n != 0) {
            continue;
        }
        int target = (totalSum * size) / n;
        if (target <= totalSum && dp[size][target]) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prevPrev = cost[0];
    int prev = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = curr;
    }
    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev = cost[i - 1] + dp[i - 1];
        int costFromPrevPrev = cost[i - 2] + dp[i - 2];
        dp[i] = Math.min(costFromPrev, costFromPrevPrev);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) with no cost
        return 0;
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    // dp[i] represents the minimum cost to reach the top from step i
    int[] dp = new int[n + 1];
    dp[n] = 0; // cost to reach top from top is 0
    dp[n - 1] = cost[n - 1]; // from last step, pay for it and then top

    for (int i = n - 2; i >= 0; i--) {
        int costOneStep = dp[i + 1];
        int costTwoStep = dp[i + 2];
        dp[i] = cost[i] + Math.min(costOneStep, costTwoStep);
    }

    return Math.min(dp[0], dp[1]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }

    int prev2 = cost[0]; // cost to reach step 0
    int prev1 = cost[1]; // cost to reach step 1
    int current = 0;

    for (int i = 2; i < n; i++) {
        current = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = current;
    }

    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start from the top directly without paying for step 0
        return 0;
    }
    // dp[i] is minimal cost to reach step i (top is step n)
    int prev2 = 0;   // dp[i-2]
    int prev1 = 0;   // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

