public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string s must not be null.");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Parameter k must be positive.");
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int value = 0;
    // Build the first k bits
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen[value] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        value = ((value << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == totalCodes) {
                return true;
            }
        }
    }
    return count == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= n - k; i++) {
        seen.add(s.substring(i, i + k));
    }
    int total = 1 << k; // may overflow for k>=31; but k <= 20 typical else unreachable
    if (total > s.length() - k + 1) return false; // not enough substrings to cover all
    return seen.size() == total;
}

