    // If 1 << k overflows (k>=31) use big integer? but we can handle k > 30 by returning false because impossible
    if (k > 20) { // because 2^20 = 1,048,576 > maximum possible distinct substrings of reasonable input sizes
        // For safety, use bit mask method but limit k to 20
    }
    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= n - k; i++) {
        seen.add(s.substring(i, i + k));
    }
    return seen.size() == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0) {
        return false;
    }
    int n = s.length();
    if (k == 0) {
        // A binary string of length 0 is trivially present
        return true;
    }
    if (n < k) {
        return false;
    }
    // Ensure k does not exceed 30 to avoid integer overflow in 1 << k
    if (k > 30) {
        // For larger k, the number of possible codes exceeds int range
        // In such a case, it's impossible to contain all codes
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;

    int current = 0;
    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    seen[current] = true;
    int countSeen = 1;

    // Slide through the string to capture all subsequent substrings of length k
    for (int i = k; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[current]) {
            seen[current] = true;
            countSeen++;
            if (countSeen == totalCodes) {
                return true; // All codes have been seen
            }
        }
    }
    return countSeen == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (k > n) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int current = 0;

    // Build the initial window of size k-1
    for (int i = 0; i < k - 1; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }

    // Slide over the string, updating the code and marking seen
    for (int i = k - 1; i < n; i++) {
        current = ((current << 1) | (s.charAt(i) - '0')) & mask;
        seen[current] = true;
    }

    // Verify that every code was seen at least once
    for (boolean flag : seen) {
        if (!flag) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    try {
        if (s == null || k <= 0) {
            return false;
        }
        int n = s.length();
        int total = 1 << k;
        if (n < total) {
            return false;
        }

        boolean[] seen = new boolean[total];
        int mask = total - 1;
        int code = 0;

        // Build initial code from first k characters
        for (int i = 0; i < k; i++) {
            code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        }
        seen[code] = true;

        // Slide window through the string
        for (int i = k; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            seen[code] = true;
        }

        // Verify that all codes were seen
        for (boolean present : seen) {
            if (!present) {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        // In case of any runtime exception (e.g., IndexOutOfBounds), return false
        return false;
    }
}

public int isPrefixOfWord(String sentence, String searchWord) {
    try {
        if (sentence == null || searchWord == null) {
            return -1;
        }
        String[] words = sentence.trim().split("\\s+");
        for (int i = 0; i < words.length; i++) {
            if (words[i].startsWith(searchWord)) {
                return i + 1; // 1‑based index
            }
        }
        return -1;
    } catch (Exception e) {
        // Any unexpected runtime issue: return -1 to signal no match
        return -1;
    }
}

