            }
        } else {
            // Unexpected character; treat as error
            throw new IllegalArgumentException(
                "String contains invalid character: " + c);
        }
    }
    // Any remaining unmatched '(' need to be closed with ')'
    insertions += balance;
    return insertions;
}

