public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long ops;
    if ((n & 1) == 0) { // n is even
        long k = n / 2L;
        ops = k * k;
    } else { // n is odd
        long k = (n - 1) / 2L;
        ops = k * (k + 1);
    }
    if (ops > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) ops;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long totalOps = 0;
    for (int i = 0; i < n; i++) {
        long value = 2L * i + 1;
        if (value > n) {
            totalOps += value - n;
        }
    }
    return (int) totalOps;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long total = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        int diff = val - n;
        if (diff > 0) {
            total += diff;
        }
    }
    // The problem guarantees that the answer fits in an int
    return (int) total;
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    long threshold = (n + 1L) / 2L;
    long count = n - threshold;
    long result = threshold * count;
    return (int) result;
}

public int minOperations(int n) {
    // Validate input
    if (n <= 0) {
        // For non-positive n, no operations are needed
        return 0;
    }
    long sumAbs = 0;
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;           // arr[i]
        sumAbs += Math.abs(value - n);   // difference from target n
    }
    // Each operation reduces the total absolute difference by 2
    long moves = sumAbs / 2;
    return (int) moves;
}

