}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(2);
    while (true) {
        int size = fibs.size();
        long next = (long)fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add((int)next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            int times = remaining / fib;
            remaining -= times * fib;
            count += times;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    if (k > 1) {
        fibs.add(b);
    }
    while (true) {
        int next = a + b;
        if (next > k) {
            break;
        }
        fibs.add(next);
        a = b;
        b = next;
    }

    // Greedy algorithm to find minimal count
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
            if (remaining == 0) {
                break;
            }
        }
    }
    return count;
}

