        if (nextLong > k) {
            break;
        }
        fib[fibSize++] = (int) nextLong;
    }
    // Greedy approach: subtract the largest Fibonacci number <= remaining
    int count = 0;
    int remaining = k;
    while (remaining > 0) {
        int low = 0, high = fibSize - 1, idx = 0;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (fib[mid] <= remaining) {
                idx = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        remaining -= fib[idx];
        count++;
    }
    return count;
}

