public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in the current folder
                break;
            default:
                // any other string represents a move into a subfolder
                depth++;
                break;
        }
    }
    return depth;
}

