public String getSmallestString(int n, int k) {
    // Validate input: length must be positive and value must be achievable
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    // Initially fill with 'a' (value 1)
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // additional value to distribute
    // Distribute the remaining value starting from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase at most 25 (from 'a' to 'z')
        result[i] = (char)(result[i] + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive.");
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k is out of the possible range for the given n.");
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int diff = k - n; // total increments needed beyond all 'a's
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int inc = Math.min(25, diff); // each position can increase up to +25 ('a'->'z')
        result[i] = (char) ('a' + inc);
        diff -= inc;
    }
    return new String(result);
}

