    int idx = n - 1;
    while (delta > 0 && idx >= 0) {
        int add = Math.min(25, delta);   // can increase char by up to 25 (from 'a' to 'z')
        res[idx] = (char)('a' + add);
        delta -= add;
        idx--;
    }
    return new String(res);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k must satisfy n <= k <= 26*n");
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int minSum = n;           // all 'a'
    int maxSum = n * 26;      // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k is out of possible range");
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a'); // initialize with 'a'
    int remaining = k - n;              // extra value to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // max increment per position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

