private static int dfs(int depth, int prev, int[] A, boolean[] used) {
    int n = A.length;
    if (depth == n) {
        return 1;
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
        if (depth > 0) {
            int sum = prev + A[i];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt != sum) continue;
        }
        used[i] = true;
        count += dfs(depth + 1, A[i], A, used);
        used[i] = false;
    }
    return count;
}

