    if (leftIndex == rightIndex) {
        // middle position: only self-mapping digits
        for (char c : new char[] {'0','1','8'}) {
            s[leftIndex] = c;
            // Check leading zero
            if (n > 1 && s[0] == '0') {
                continue;
            }
            result.add(new String(s));
        }
        return;
    }
    // else leftIndex < rightIndex
    for (int i=0; i<leftDigits.length; i++) {
        s[leftIndex] = leftDigits[i];
        s[rightIndex] = rightDigits[i];
        // skip leading zero
        if (n > 1 && s[0] == '0') {
            continue;
        }
        backtrack(leftIndex+1, rightIndex-1, s);
    }
}

void backtrack(int l, int r) {
        if (l > r) {
            result.add(new String(s));
            return;
        }
        if (l == r) {
            for (char c : new char[] {'0','1','8'}) {
                s[l] = c;
                if (n>1 && s[0]=='0') continue;
                result.add(new String(s));
            }
            return;
        }
        for (int i=0; i<leftDigits.length; i++) {
            s[l] = leftDigits[i];
            s[r] = rightDigits[i];
            if (n>1 && s[0]=='0') continue;
            backtrack(l+1, r-1);
        }
    }

