private static List<String> buildSymmetric(int currLen, int totalLen) {
    List<String> result = new ArrayList<>();
    if (currLen == 0) {
        result.add("");
        return result;
    }
    if (currLen == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    List<String> sub = buildSymmetric(currLen - 2, totalLen);
    int[][] pairs = {{1, 1}, {6, 9}, {8, 8}, {9, 6}};
    for (String middle : sub) {
        for (int[] p : pairs) {
            if (currLen == totalLen && p[0] == 0) {
                continue; // avoid leading zero
            }
            result.add("" + p[0] + middle + p[1]);
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
