public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        // Negative input is invalid; return -1 to indicate error
        return -1;
    }
    // dp[i] will hold the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0; // zero requires zero squares

    for (int i = 1; i <= n; i++) {
        int minCount = Integer.MAX_VALUE;
        // Iterate over all perfect squares <= i
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < minCount) {
                minCount = candidate;
            }
        }
        dp[i] = minCount;
    }
    return dp[n];
}

